#include <iostream>
using namespace std;

// 顺序查找 ST[0]作为哨兵
int Sequential_Search(int* ST, int n, int key) {
    ST[0] = key;  // 哨兵：免去边界检查
    int i = n;
    while (ST[i] != key) i--;
    return i;  // 返回0表示失败
}

// 折半查找（ST必须有序）
int Binary_Search(int* ST, int n, int key) {
    int low = 1, high = n;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (ST[mid] == key) return mid;
        else if (ST[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return 0;
}

// 折半查找的递归实现
int Binary_Search_Rec(int* ST, int low, int high, int key) {
    if (low > high) return 0;
    int mid = (low + high) / 2;
    if (ST[mid] == key) return mid;
    else if (ST[mid] < key)
        return Binary_Search_Rec(ST, mid+1, high, key);
    else
        return Binary_Search_Rec(ST, low, mid-1, key);
}

// 时间复杂度分析
// 顺序查找: O(n), ASL = (n+1)/2
// 折半查找: O(log n), ASL ≈ log2(n+1) - 1
//
// 折半查找判定树深度: ⎣log2(n)⎦ + 1
// 查找成功比较次数: 不超过判定树深度

#include <iostream>
using namespace std;

typedef struct BiTNode {
    int data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

// 查找
BiTNode* BST_Search(BiTree T, int key) {
    if (!T || T->data == key) return T;
    return key < T->data ? BST_Search(T->lchild, key) : BST_Search(T->rchild, key);
}

// 插入
bool BST_Insert(BiTree &T, int key) {
    if (!T) {
        T = new BiTNode;
        T->data = key;
        T->lchild = T->rchild = NULL;
        return true;
    }
    if (key == T->data) return false;
    return key < T->data ? BST_Insert(T->lchild, key) : BST_Insert(T->rchild, key);
}

// 删除
bool BST_Delete(BiTree &T, int key) {
    if (!T) return false;
    if (key == T->data) {
        BiTree q = T;
        if (!T->lchild) T = T->rchild;       // 左空
        else if (!T->rchild) T = T->lchild;  // 右空
        else {  // 左右都不空，用直接前驱替代
            BiTree s = T->lchild, parent = T;
            while (s->rchild) { parent = s; s = s->rchild; }  // 找前驱
            // s是T的左子树中最右结点，作为前驱
            s->rchild = T->rchild;  // s的右指向T的右
            if (parent != T) parent->rchild = s->lchild;  // s的双亲的右指向s的左
            else parent->lchild = s->lchild;              // s是T的直接左孩子
            // 这里的实现较简略，更标准做法是: 前驱的值替换T的值，然后删除前驱
            // 更简单：T->data = s->data; BST_Delete(T->lchild, s->data);
        }
        delete q;
        return true;
    }
    return key < T->data ? BST_Delete(T->lchild, key) : BST_Delete(T->rchild, key);
}

// 中序遍历（BST的中序遍历是递增序列！）
void InOrder(BiTree T) {
    if (T) { InOrder(T->lchild); cout << T->data << " "; InOrder(T->rchild); }
}

// 性能: 平均O(log n), 最坏O(n)（单支树）
// 平衡树（AVL）保证最坏也为O(log n)

#include <iostream>
#include <vector>
#include <list>
using namespace std;

class HashTable {
private:
    vector<list<int>> table;
    int size;  // 哈希表大小

    // 哈希函数: 除留余数法
    int hash(int key) { return key % size; }

public:
    HashTable(int m) : size(m) { table.resize(m); }

    // 查找
    bool search(int key) {
        int idx = hash(key);
        for (int x : table[idx]) if (x == key) return true;
        return false;
    }

    // 插入
    void insert(int key) {
        int idx = hash(key);
        // 可先检查是否已存在
        for (int x : table[idx]) if (x == key) return;
        table[idx].push_front(key);  // 头插
    }

    // 删除
    bool remove(int key) {
        int idx = hash(key);
        for (auto it = table[idx].begin(); it != table[idx].end(); ++it)
            if (*it == key) { table[idx].erase(it); return true; }
        return false;
    }
};

// 装填因子 α = n/m
// 链地址法成功ASL ≈ 1 + α/2
// 与开放定址法比较: 链地址法无二次聚集，可直接删除
//
// 哈希函数选择: 除留余数法 key % p
//   p应为质数或不含小质因子，p ≤ m
//
// 开放定址法冲突处理: Hi = (H + di) % m
//   线性探测: di = 1,2,3... 易产生二次聚集
//   二次探测: di = 1,-1,4,-4,9,-9...
